import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (mocking: inprocess, fake).
const prices = { A: 10, B: 25.5, BIG: 60 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order without discount at or below 100', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }] })) // 71
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.match(r.body.id, /^\d+$/)
  assert.deepEqual(r.body.items, [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }])
  assert.equal(r.body.total, 71)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders: total above 100 gets 10% off, floored', async () => {
  const r = await json(await post({ items: [{ sku: 'BIG', qty: 2 }] })) // 120 -> 108
  assert.equal(r.status, 201)
  assert.equal(r.body.total, 108)
  const f = await json(await post({ items: [{ sku: 'B', qty: 5 }] })) // 127.5 -> 114.75 -> 114
  assert.equal(f.body.total, 114)
})

test('POST /orders: total is floored when no discount applies', async () => {
  const r = await json(await post({ items: [{ sku: 'B', qty: 1 }] })) // 25.5
  assert.equal(r.body.total, 25)
})

test('POST /orders ids are sequential strings', async () => {
  const a = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
  assert.equal(typeof a.body.id, 'string')
})

test('POST /orders: unknown sku yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — pricing returns undefined, NaN total is serialized as null, still 201
  const r = await json(await post({ items: [{ sku: 'NOPE', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders: missing qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no item validation, undefined qty gives NaN
  const r = await json(await post({ items: [{ sku: 'A' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

